using MediatR;using OAS.Application.Abstractions.Persistence;using OAS.Application.Accounting.Abstractions;using OAS.Application.Accounting.Suppliers.Specifications;using OAS.Application.Common.Exceptions;using OAS.Domain.Accounting.Entities;using OAS.Domain.Accounting.ValueObjects;
using DomainContactMethod=OAS.Domain.Accounting.Enums.ContactMethod;using DomainPartyEntityType=OAS.Domain.Accounting.Enums.PartyEntityType;using DomainSupplierScope=OAS.Domain.Accounting.Enums.SupplierScope;
namespace OAS.Application.Accounting.Suppliers.Commands.UpdateSupplier;
public sealed class UpdateSupplierCommandHandler(IRepository<Supplier,Guid> suppliers,IPartyAccountProvisioningService accounts):IRequestHandler<UpdateSupplierCommand>
{public async Task Handle(UpdateSupplierCommand request,CancellationToken ct){var e=await suppliers.GetForUpdateAsync(request.Id,ct)??throw new NotFoundException(nameof(Supplier),request.Id);Ensure(request.Request.RowVersion,e.RowVersion);var d=request.Request;if(!string.IsNullOrWhiteSpace(d.NationalId)&&await suppliers.CountAsync(SupplierSpecifications.ByNationalId(d.NationalId.Trim(),e.Id),ct)>0)throw new ConflictException("accounting_supplier_national_id_duplicate","National id is already in use.");if(!string.IsNullOrWhiteSpace(d.TaxNumber)&&await suppliers.CountAsync(SupplierSpecifications.ByTaxNumber(d.TaxNumber.Trim(),e.Id),ct)>0)throw new ConflictException("accounting_supplier_tax_number_duplicate","Tax number is already in use.");if(!string.IsNullOrWhiteSpace(d.CommercialRegistrationNo)&&await suppliers.CountAsync(SupplierSpecifications.ByCommercialRegistration(d.CommercialRegistrationNo.Trim(),e.Id),ct)>0)throw new ConflictException("accounting_supplier_cr_duplicate","Commercial registration number is already in use.");var c=PartyContactInfo.Create(d.ContactPersonName,d.ContactPersonTitle,d.Phone,d.Mobile,d.AlternatePhone,d.WhatsAppNumber,d.Email,d.Website,(DomainContactMethod)(byte)d.PreferredContactMethod,PartyAddress.Create(d.Country,d.Governorate,d.City,d.District,d.Street,d.Building,d.PostalCode,d.AddressDetails));e.UpdateDetails((DomainPartyEntityType)(byte)d.EntityType,(DomainSupplierScope)(byte)d.SupplierScope,d.NameAr,d.NameEn,d.TradeName,d.NationalId,d.CommercialRegistrationNo,d.TaxNumber,c,d.CreditLimit,d.PaymentTermDays,d.DefaultLeadTimeDays,d.SupplierSince,d.Notes);suppliers.Update(e);await accounts.SynchronizeAsync(e.AccountId,e.NameAr,e.NameEn,null,ct);}private static void Ensure(string rv,byte[] current){try{if(!Convert.FromBase64String(rv).SequenceEqual(current))throw new ConcurrencyException("Supplier was modified by another user.");}catch(FormatException ex){throw new ConcurrencyException("Supplier row version is invalid.",ex);}}}
